/**
 * Surface textures (section 11.3), generated by tools/gen-textures.ts and served from host/public/textures/.
 * Albedo maps are sRGB. Normal maps are derived here from the height maps (smaller downloads), with wrap-around
 * so they tile like their albedo. Everything repeats, has mipmaps and the renderer's anisotropy (8 or more on the
 * road). The Low tier loads the half-size `_lo` set.
 */
import * as THREE from 'three';

export interface SurfaceTex {
  map: THREE.Texture;
  normal: THREE.Texture;
}

export interface Textures {
  asphalt: SurfaceTex;
  grass: SurfaceTex;
  dirt: SurfaceTex;
  rock: SurfaceTex;
  snow: SurfaceTex;
  sand: SurfaceTex;
  gravel: SurfaceTex;
  concrete: SurfaceTex;
  /** Road wear masks: R patch repairs, G cracks, B oil stains (48 m per tile). */
  detail: THREE.Texture;
  /** Low-frequency variation (160 m per tile) that breaks up repetition. */
  macro: THREE.Texture;
  dispose(): void;
}

let loaded: Textures | null = null;

/** The loaded set (call loadTextures first). */
export function textures(): Textures {
  if (!loaded) throw new Error('textures are not loaded yet');
  return loaded;
}

async function image(url: string): Promise<HTMLImageElement> {
  const im = new Image();
  im.src = url;
  await im.decode();
  return im;
}

function setup(t: THREE.Texture, srgb: boolean, aniso: number): THREE.Texture {
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.anisotropy = aniso;
  t.needsUpdate = true;
  return t;
}

/** Tangent-space normal map from a tileable height map (central differences with wrap-around). */
function normalFromHeight(im: HTMLImageElement, strength: number, aniso: number): THREE.Texture {
  const w = im.width,
    h = im.height;
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d', { willReadFrequently: true })!;
  g.drawImage(im, 0, 0);
  const src = g.getImageData(0, 0, w, h).data;
  const out = g.createImageData(w, h);
  const H = (x: number, y: number): number => src[(((y + h) % h) * w + ((x + w) % w)) * 4]! / 255;
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const dx = (H(x + 1, y) - H(x - 1, y)) * strength,
        dy = (H(x, y + 1) - H(x, y - 1)) * strength;
      const l = Math.hypot(dx, dy, 1);
      const o = (y * w + x) * 4;
      out.data[o] = ((-dx / l) * 0.5 + 0.5) * 255;
      out.data[o + 1] = ((dy / l) * 0.5 + 0.5) * 255;
      out.data[o + 2] = ((1 / l) * 0.5 + 0.5) * 255;
      out.data[o + 3] = 255;
    }
  g.putImageData(out, 0, 0);
  return setup(new THREE.CanvasTexture(c), false, aniso);
}

/** Bumpiness of each surface's normal map. */
const STRENGTH: Record<string, number> = {
  asphalt: 2.2,
  grass: 1.6,
  dirt: 2.2,
  rock: 3.2,
  snow: 1.1,
  sand: 1.6,
  gravel: 3.4,
  concrete: 1.2,
};

export async function loadTextures(lo: boolean, aniso: number): Promise<Textures> {
  if (loaded) return loaded;
  const sfx = lo ? '_lo' : '';
  const all: THREE.Texture[] = [];
  const surf = async (name: string, roadAniso = false): Promise<SurfaceTex> => {
    const [a, hm] = await Promise.all([image(`/textures/${name}${sfx}.png`), image(`/textures/${name}_h${sfx}.png`)]);
    const an = roadAniso ? Math.max(8, aniso) : Math.min(8, aniso);
    const s = { map: setup(new THREE.Texture(a), true, an), normal: normalFromHeight(hm, STRENGTH[name] ?? 2, an) };
    all.push(s.map, s.normal);
    return s;
  };
  const lin = async (name: string): Promise<THREE.Texture> => {
    const t = setup(new THREE.Texture(await image(`/textures/${name}${sfx}.png`)), false, Math.min(8, aniso));
    all.push(t);
    return t;
  };
  const [asphalt, grass, dirt, rock, snow, sand, gravel, concrete, detail, macro] = await Promise.all([
    surf('asphalt', true),
    surf('grass'),
    surf('dirt'),
    surf('rock'),
    surf('snow'),
    surf('sand'),
    surf('gravel'),
    surf('concrete'),
    lin('detail'),
    lin('macro'),
  ]);
  loaded = {
    asphalt,
    grass,
    dirt,
    rock,
    snow,
    sand,
    gravel,
    concrete,
    detail,
    macro,
    dispose() {
      for (const t of all) t.dispose();
      loaded = null;
    },
  };
  return loaded;
}
